/// <summary>
///     The <c>AVASalesOrderCopyingContractCls_Extension</c> class is the extension for <c>SalesQuotationController</c>
/// </summary>
[ExtensionOf(classStr(SalesQuotationController))]
final class AVASalesQuotationContollerCls_Extension
{
}

Method.Source:
    /// <summary>
/// Subscribing to the <c>renderingComplete</c> event.
/// </summary>
protected void preRunModifyContract()
{
    next preRunModifyContract();
    this.renderingCompleted += eventhandler(AVASalesQuotationEditLinesFormSalesSend_Extension::renderingCompleted);
}

/// <summary>
/// Gets the Sales Quotation report title.
/// </summary>
/// <returns>
/// The report title.
/// </returns>
protected str documentTitle()
{
    str quotationTxt;
    CustQuotationJour   locCustQuotationJour;
    CustQuotationJour   locCustQuotationJourReload;
    PrintCopyOriginal   locPrintCopyOriginal;
    str                 locInqueryType;

    locCustQuotationJour    = custQuotationJour;
    locCustQuotationJourReload = CustQuotationJour::findRecId(locCustQuotationJour.RecId);
    locPrintCopyOriginal    = printCopyOriginal;
    locInqueryType          = inqueryType;

    quotationTxt = next documentTitle();

    if ((inqueryType != "@SYS12529" ) || (locCustQuotationJour.showQuotationStatus() != SalesQuotationStatus::Confirmed))
    {
        if (locPrintCopyOriginal == PrintCopyOriginal::Copy)
        {
            if (    locCustQuotationJourReload.KCS_SendMode == KCS_SendMode::Proforma
                ||  locCustQuotationJour.isProforma()                                   )   // isProforma() seems to be implemented but without any meaning 
            {
                //quotationTxt = literalStr("@SYS70791");
                quotationTxt = literalStr("@NDX:NXAProformaQuotationCopyMaterial");
            }
            else
            {
                //quotationTxt = literalStr("@SYS24431");
                quotationTxt = literalStr("@NDX:NXAQuotationCopyMaterial");
            }
        }
        else
        {
            if (    locCustQuotationJourReload.KCS_SendMode == KCS_SendMode::Proforma
                ||  locCustQuotationJour.isProforma()                                   )   // isProforma() seems to be implemented but without any meaning
            {
                //quotationTxt = literalStr("@SYS269");
                quotationTxt = literalStr("@NDX:NXAProformaQuotationMaterial");
            }
            else
            {
                //quotationTxt = literalStr("@SYS5864");
                quotationTxt = literalStr("@NDX:NXAQuotationMaterial");
            }
        }
    }

    return quotationTxt;
}
